function lruResults(capacity, operations) {
    const entries = [];
    const results = [];
    for (const operation of operations) {
        const key = operation[1];
        const index = entries.findIndex((entry) => entry.key === key);
        if (operation[0] === "get") {
            if (index === -1) {
                results.push(-1);
            } else {
                const [entry] = entries.splice(index, 1);
                entries.push(entry);
                results.push(entry.value);
            }
        } else {
            if (index !== -1)
                entries.splice(index, 1);
            entries.push({ key, value: operation[2] });
            if (entries.length > capacity)
                entries.shift();
        }
    }
    return results;
}

function lruResults(capacity, operations) {
    const cache = new Map();
    const results = [];
    for (const operation of operations) {
        const key = operation[1];
        if (operation[0] === "get") {
            if (!cache.has(key)) {
                results.push(-1);
                continue;
            }
            const value = cache.get(key);
            cache.delete(key);
            cache.set(key, value);
            results.push(value);
        } else {
            cache.delete(key);
            cache.set(key, operation[2]);
            if (cache.size > capacity)
                cache.delete(cache.keys().next().value);
        }
    }
    return results;
}
